-- identity-1-estate.commit.sql
--
-- ============================== COMMIT - THIS WRITES ==============================
-- Byte-identical to the preflight twin except this banner and the terminal statement:
-- COMMIT TRANSACTION here, ROLLBACK TRANSACTION there. The preflight is optional: this file verifies everything inside
-- its transaction and keeps nothing when a check fails.
--
-- WHAT THIS DOES, in one transaction on the estate database:
--   1. retains, through model.mint_content_artifact, the bytes of the canonical features of sign-up
--      (nerdery-register-wildlife-user) and sign-in (nerdery-sign-in-wildlife-user) and the promise flight-promise:nerdery-dnr-sign-up-and-sign-in;
--   2. compiles nerdery-sign-in-wildlife-user's DSL with the installed compiler against those bytes: COMPILED to
--      sha256:8d80e177396ad14f72b937aab911022b68f12b34b25fcd03628a9b8c21f389d9, the document the flight declares.
-- WHERE: the estate database. Run the whole file in one session (under a minute).
-- BASES: compiler body sha256:a437984d1e7691557b473adb9b1650467ecb67a40e9a6b1251f4f7c01d3a9a81, mint sha256:d6f8025a8c5e0d891a50d11df06dc0f2a1785eb7bdd977d0cd45e89eaca2516e, the no-drift check installed.
-- RESULT SETS: base; minted (3 rows); readback (retained 1 each); compile (status COMPILED, document = expected).
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @cd nvarchar(max)=REPLACE(OBJECT_DEFINITION(OBJECT_ID(N'analysis.compile_capability_dsl')),NCHAR(13)+NCHAR(10),NCHAR(10));
SET @cd=SUBSTRING(@cd,CHARINDEX(N'PROCEDURE analysis.compile_capability_dsl',@cd),DATALENGTH(@cd)/2);
WHILE DATALENGTH(@cd)>0 AND RIGHT(@cd,1) IN (NCHAR(10),NCHAR(13),NCHAR(32),NCHAR(9)) SET @cd=LEFT(@cd,DATALENGTH(@cd)/2-1);
DECLARE @cd_digest varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),@cd COLLATE Latin1_General_100_BIN2_UTF8)),2));
DECLARE @m varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),OBJECT_DEFINITION(OBJECT_ID(N'model.mint_content_artifact')) COLLATE Latin1_General_100_BIN2_UTF8)),2));
DECLARE @check int=CASE WHEN OBJECT_ID(N'analysis.check_capability_feature_conformance') IS NOT NULL THEN 1 ELSE 0 END;
SELECT N'base' AS result_set,@cd_digest AS compiler_body,'sha256:a437984d1e7691557b473adb9b1650467ecb67a40e9a6b1251f4f7c01d3a9a81' AS compiler_expected,@m AS mint_installed,@check AS check_installed;
IF @cd_digest IS NULL OR @cd_digest<>'sha256:a437984d1e7691557b473adb9b1650467ecb67a40e9a6b1251f4f7c01d3a9a81' OR @m IS NULL OR @m<>'sha256:d6f8025a8c5e0d891a50d11df06dc0f2a1785eb7bdd977d0cd45e89eaca2516e' OR @check<>1
BEGIN
 RAISERROR(N'IDENTITY1_BASE: the compiler, the mint or the check is not the reviewed base; nothing is changed.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
GO
SET NOCOUNT ON;
DECLARE @minted TABLE(ordinal int IDENTITY(1,1),value nvarchar(max));
INSERT @minted(value) EXEC model.mint_content_artifact @document=N'{"artifactKind":"capability-feature:nerdery-sign-in-wildlife-user","text":"# nerdery-sign-in-wildlife-user: canonical-feature candidate for owner review, 2026-11-02.\n# Product authority: source/nerdery-architecture-design-challenge.pdf, identified in source/source-manifest.json.\n# Authoring convention: the two supplied canonical feature examples; not a new platform format.\n# Status: finalized for the SideFX build from the owner-review candidate\n# nerdery-canonical-features/features/mvp/nerdery-sign-in-wildlife-user.feature (sha256:9ab0770a4aef7c2ee68dcdc276a913b64ee5161911f5b843e6b0aa35b6ae2e51).\n# @status:probed: the case ran read-only against the wildlife procedures through nerdery/conformance/run-cases.mjs\n# (runs 8a8f1f45, 59995dd3, e8a9ae1e, d6230231).\n# Every Scenario below is an acceptance case of the ONE circuit scenario tagged on this Feature.\n# Given / When / Then are exact across cases. Given holds the request JSON. Then holds operation/path/equals.\n# Values: true/false/null/numbers/arrays/objects are JSON values; other values are strings; (absent) selects nothing.\n# Authentication, fixture state and dependency behavior come from the pinned test arrangement, never caller role claims.\n# Provider: the operation is one sql-database-reader statement on sfx-identity (EXEC wildlife.serve), so every case is\n# tagged @provider:sql-database-reader. The DNR identity service is its stand-in, wildlife.identity_response, which holds\n# the fixture''s identity responses by reference (D02); a signed-in session is the verified SideFX session it binds.\n# See review/provider-bindings.md for provider scope, evidence and open bindings. Fixture preparation is separate.\n# A successful write requires durable provider testimony and independent read-back; output echoes are not proof.\n# All JSON shapes/identities are proposed under D01. Case design decisions remain proposals, not Nerdery requirements.\n# Scope: mvp. Source requirements: NRD-U05.\n# Proposed outcome contract: nerdery-sign-in-wildlife-user-result.v1; terminal variants: SIGNED_IN, REFUSED.\n# Proposed operation identity: nerdery-sign-in-wildlife-user.sign-in.\n\n@capability:nerdery-sign-in-wildlife-user\n@root-scenario:nerdery-sign-in-wildlife-user\n@scenario:nerdery-sign-in-wildlife-user\n@input:nerdery-sign-in-wildlife-user-request\n@input-contract:nerdery-sign-in-wildlife-user-request.v1\n@event:nerdery-sign-in-wildlife-user-requested\n@event-authority:nerdery-sign-in-wildlife-user.v1\n@outcome:nerdery-sign-in-wildlife-user-outcome\n@outcome-contract:nerdery-sign-in-wildlife-user-result.v1\n@outcome-terminal\nFeature: Sign in to the wildlife application\n  As a registered user\n  I want to sign in through the DNR identity service\n  So that I can use my own collection and team\n\n  Rule: Only a validated DNR identity establishes an application session\n\n    # Source requirements: NRD-U05.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-sign-in-citizen.json (sha256:705562dd0876edf3143d6df117011b2df3d4b98b6fac7094450bf141e4c19c68).\n    @case:nrd-sign-in-citizen\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: A citizen can sign in\n      Given a DNR sign-in response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-a\"\n        }\n        \"\"\"\n      And the validated DNR subject belongs to Avery''s registered citizen account\n      When the wildlife sign-in is completed\n      Then the user has an authenticated application session or a named sign-in refusal\n        | operation | path | equals |\n        | nerdery-sign-in-wildlife-user.sign-in | $.status | SIGNED_IN |\n        | nerdery-sign-in-wildlife-user.sign-in | $.user.userId | user-a |\n        | nerdery-sign-in-wildlife-user.sign-in | $.session.established | true |\n\n    # Source requirements: NRD-U05.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-sign-in-biologist.json (sha256:e61706eb3de0e70e4ffed025d95aa13d995f7090fd9ff2c408ac0fba23826837).\n    @case:nrd-sign-in-biologist\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: A biologist can sign in\n      Given a DNR sign-in response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-bio\"\n        }\n        \"\"\"\n      And the validated DNR subject belongs to Casey''s registered biologist account\n      When the wildlife sign-in is completed\n      Then the user has an authenticated application session or a named sign-in refusal\n        | operation | path | equals |\n        | nerdery-sign-in-wildlife-user.sign-in | $.status | SIGNED_IN |\n        | nerdery-sign-in-wildlife-user.sign-in | $.user.userId | user-bio |\n        | nerdery-sign-in-wildlife-user.sign-in | $.session.established | true |\n\n    # Source requirements: NRD-U05.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-sign-in-invalid.json (sha256:d2e434cfc9636518a7a5de45bf6f5d6e3ff9f344c5f85eb42a0d8de42c543c35).\n    @case:nrd-sign-in-invalid\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: An invalid identity response cannot establish a session\n      Given a DNR sign-in response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-invalid\"\n        }\n        \"\"\"\n      And the DNR identity response failed validation\n      When the wildlife sign-in is completed\n      Then the user has an authenticated application session or a named sign-in refusal\n        | operation | path | equals |\n        | nerdery-sign-in-wildlife-user.sign-in | $.status | REFUSED |\n        | nerdery-sign-in-wildlife-user.sign-in | $.reason.code | IDENTITY_NOT_VALIDATED |\n        | nerdery-sign-in-wildlife-user.sign-in | $.session.established | false |\n\n    # Source requirements: NRD-U05.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-sign-in-expired.json (sha256:0ea34a3c6008827eb6d356e54850dfa6ac33a8c67330b2c1a7dadd403fdf721b).\n    @case:nrd-sign-in-expired\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: An expired identity response cannot establish a session\n      Given a DNR sign-in response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-expired\"\n        }\n        \"\"\"\n      And the referenced DNR identity response has expired\n      When the wildlife sign-in is completed\n      Then the user has an authenticated application session or a named sign-in refusal\n        | operation | path | equals |\n        | nerdery-sign-in-wildlife-user.sign-in | $.status | REFUSED |\n        | nerdery-sign-in-wildlife-user.sign-in | $.reason.code | IDENTITY_RESPONSE_EXPIRED |\n        | nerdery-sign-in-wildlife-user.sign-in | $.session.established | false |\n\n    # Source requirements: NRD-U05.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-sign-in-unavailable.json (sha256:f5fd5ba3c2834900b85b010ea70ec7ccdfe760087b400e4f12925f9d95ca736a).\n    @case:nrd-sign-in-unavailable\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: Sign-in reports an identity dependency failure\n      Given a DNR sign-in response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-a\"\n        }\n        \"\"\"\n      And the identity service is unavailable and no application session has been established\n      When the wildlife sign-in is completed\n      Then the user has an authenticated application session or a named sign-in refusal\n        | operation | path | equals |\n        | nerdery-sign-in-wildlife-user.sign-in | $.status | REFUSED |\n        | nerdery-sign-in-wildlife-user.sign-in | $.reason.code | IDENTITY_SERVICE_UNAVAILABLE |\n        | nerdery-sign-in-wildlife-user.sign-in | $.session.established | false |\n"}';
INSERT @minted(value) EXEC model.mint_content_artifact @document=N'{"artifactKind":"capability-feature:nerdery-register-wildlife-user","text":"# nerdery-register-wildlife-user: canonical-feature candidate for owner review, 2026-11-02.\n# Product authority: source/nerdery-architecture-design-challenge.pdf, identified in source/source-manifest.json.\n# Authoring convention: the two supplied canonical feature examples; not a new platform format.\n# Status: finalized for the SideFX build from the owner-review candidate\n# nerdery-canonical-features/features/mvp/nerdery-register-wildlife-user.feature (sha256:cb3a603d253356500369870cc1ca44bda98f8c2100aa229fb5134e371adff146).\n# @status:probed: the case ran read-only against the wildlife procedures through nerdery/conformance/run-cases.mjs\n# (runs 8a8f1f45, 59995dd3, e8a9ae1e, d6230231).\n# Every Scenario below is an acceptance case of the ONE circuit scenario tagged on this Feature.\n# Given / When / Then are exact across cases. Given holds the request JSON. Then holds operation/path/equals.\n# Values: true/false/null/numbers/arrays/objects are JSON values; other values are strings; (absent) selects nothing.\n# Authentication, fixture state and dependency behavior come from the pinned test arrangement, never caller role claims.\n# Provider: the operation is one sql-database-reader statement on sfx-identity (EXEC wildlife.serve), so every case is\n# tagged @provider:sql-database-reader. The DNR identity service is its stand-in, wildlife.identity_response, which holds\n# the fixture''s identity responses by reference (D02); a signed-in session is the verified SideFX session it binds.\n# See review/provider-bindings.md for provider scope, evidence and open bindings. Fixture preparation is separate.\n# A successful write requires durable provider testimony and independent read-back; output echoes are not proof.\n# All JSON shapes/identities are proposed under D01. Case design decisions remain proposals, not Nerdery requirements.\n# Scope: mvp. Source requirements: NRD-U05, NRD-U06.\n# Proposed outcome contract: nerdery-register-wildlife-user-result.v1; terminal variants: REGISTERED, REFUSED.\n# Proposed operation identity: nerdery-register-wildlife-user.register.\n\n@capability:nerdery-register-wildlife-user\n@root-scenario:nerdery-register-wildlife-user\n@scenario:nerdery-register-wildlife-user\n@input:nerdery-register-wildlife-user-request\n@input-contract:nerdery-register-wildlife-user-request.v1\n@event:nerdery-register-wildlife-user-requested\n@event-authority:nerdery-register-wildlife-user.v1\n@outcome:nerdery-register-wildlife-user-outcome\n@outcome-contract:nerdery-register-wildlife-user-result.v1\n@outcome-terminal\nFeature: Register a wildlife user through the DNR identity service\n  As a state citizen\n  I want to complete account registration using the DNR identity service\n  So that I can keep my own wildlife collection\n\n  Rule: A validated DNR identity establishes a user with the required profile and a unique email\n\n    # Source requirements: NRD-U05, NRD-U06.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-registration-created.json (sha256:240613f1d9122206687161c5fbe6c3cf3c5f30dc2d5695885f5100eab704083e).\n    @case:nrd-registration-created\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: A new DNR identity establishes an account\n      Given a DNR registration response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-new\"\n        }\n        \"\"\"\n      And DNR has validated Drew''s identity and no wildlife account uses Drew''s email\n      When the wildlife account registration is completed\n      Then the user has one wildlife account or a named registration refusal\n        | operation | path | equals |\n        | nerdery-register-wildlife-user.register | $.status | REGISTERED |\n        | nerdery-register-wildlife-user.register | $.user.firstName | Drew |\n        | nerdery-register-wildlife-user.register | $.user.lastName | Citizen |\n        | nerdery-register-wildlife-user.register | $.user.email | drew@example.test |\n        | nerdery-register-wildlife-user.register | $.mutation.applied | true |\n\n    # Source requirements: NRD-U05, NRD-U06.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-registration-duplicate-email.json (sha256:b26854afedfb8be4a14f559f2310404b266475744b9aa63168054226932646f9).\n    @case:nrd-registration-duplicate-email\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: A different DNR subject cannot claim an existing email\n      Given a DNR registration response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-duplicate-email\"\n        }\n        \"\"\"\n      And DNR validated a different subject with the email already registered to Avery\n      When the wildlife account registration is completed\n      Then the user has one wildlife account or a named registration refusal\n        | operation | path | equals |\n        | nerdery-register-wildlife-user.register | $.status | REFUSED |\n        | nerdery-register-wildlife-user.register | $.reason.code | EMAIL_NOT_UNIQUE |\n        | nerdery-register-wildlife-user.register | $.mutation.applied | false |\n        | nerdery-register-wildlife-user.register | $.user | (absent) |\n\n    # Source requirements: NRD-U05, NRD-U06.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-registration-missing-firstname.json (sha256:a9eed05965d82cf1e2046dbc1ba879224d1dab0bd545b7a06a32b3b1a950bab9).\n    @case:nrd-registration-missing-firstname\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: Registering a user requires first name\n      Given a DNR registration response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-missing\"\n        }\n        \"\"\"\n      And DNR validated the new subject but its profile lacks the field named in this case\n      When the wildlife account registration is completed\n      Then the user has one wildlife account or a named registration refusal\n        | operation | path | equals |\n        | nerdery-register-wildlife-user.register | $.status | REFUSED |\n        | nerdery-register-wildlife-user.register | $.reason.code | USER_PROFILE_INCOMPLETE |\n        | nerdery-register-wildlife-user.register | $.mutation.applied | false |\n        | nerdery-register-wildlife-user.register | $.user | (absent) |\n\n    # Source requirements: NRD-U05, NRD-U06.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-registration-missing-lastname.json (sha256:01d2b1da5bacff0f7e633869231030c49726a0ff3c1470f566ea4fd7b4c455ac).\n    @case:nrd-registration-missing-lastname\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: Registering a user requires last name\n      Given a DNR registration response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-missing\"\n        }\n        \"\"\"\n      And DNR validated the new subject but its profile lacks the field named in this case\n      When the wildlife account registration is completed\n      Then the user has one wildlife account or a named registration refusal\n        | operation | path | equals |\n        | nerdery-register-wildlife-user.register | $.status | REFUSED |\n        | nerdery-register-wildlife-user.register | $.reason.code | USER_PROFILE_INCOMPLETE |\n        | nerdery-register-wildlife-user.register | $.mutation.applied | false |\n        | nerdery-register-wildlife-user.register | $.user | (absent) |\n\n    # Source requirements: NRD-U05, NRD-U06.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-registration-missing-email.json (sha256:5e2e9c0dfa65f7008a764e7975ed53d92d7a6431a57b568b6fcf4436ec696d94).\n    @case:nrd-registration-missing-email\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: Registering a user requires email address\n      Given a DNR registration response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-missing\"\n        }\n        \"\"\"\n      And DNR validated the new subject but its profile lacks the field named in this case\n      When the wildlife account registration is completed\n      Then the user has one wildlife account or a named registration refusal\n        | operation | path | equals |\n        | nerdery-register-wildlife-user.register | $.status | REFUSED |\n        | nerdery-register-wildlife-user.register | $.reason.code | USER_PROFILE_INCOMPLETE |\n        | nerdery-register-wildlife-user.register | $.mutation.applied | false |\n        | nerdery-register-wildlife-user.register | $.user | (absent) |\n\n    # Source requirements: NRD-U05.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-registration-untrusted-identity.json (sha256:6b8645561ce36b0b3bb7120d526c9d505e95c6d8c07bb45c68782f1f33d4ade0).\n    @case:nrd-registration-untrusted-identity\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: An unvalidated identity response cannot create an account\n      Given a DNR registration response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-invalid\"\n        }\n        \"\"\"\n      And the referenced DNR response has failed identity validation\n      When the wildlife account registration is completed\n      Then the user has one wildlife account or a named registration refusal\n        | operation | path | equals |\n        | nerdery-register-wildlife-user.register | $.status | REFUSED |\n        | nerdery-register-wildlife-user.register | $.reason.code | IDENTITY_NOT_VALIDATED |\n        | nerdery-register-wildlife-user.register | $.mutation.applied | false |\n        | nerdery-register-wildlife-user.register | $.user | (absent) |\n\n    # Source requirements: NRD-U05.\n    # Proposed decisions: D01, D02.\n    # Arrangement: nerdery-canonical-features/fixtures/cases/nrd-registration-provider-unavailable.json (sha256:0a263f02e4a10790c71ac3a94bf0846393eaf7433f82f6317c211abbf1013bba).\n    @case:nrd-registration-provider-unavailable\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: An unavailable identity service does not yield a fabricated account\n      Given a DNR registration response reference\n        \"\"\"json\n        {\n          \"identityResponseRef\": \"identity-new\"\n        }\n        \"\"\"\n      And the DNR identity service is unavailable before it can validate the registration\n      When the wildlife account registration is completed\n      Then the user has one wildlife account or a named registration refusal\n        | operation | path | equals |\n        | nerdery-register-wildlife-user.register | $.status | REFUSED |\n        | nerdery-register-wildlife-user.register | $.reason.code | IDENTITY_SERVICE_UNAVAILABLE |\n        | nerdery-register-wildlife-user.register | $.mutation.applied | false |\n        | nerdery-register-wildlife-user.register | $.user | (absent) |\n"}';
INSERT @minted(value) EXEC model.mint_content_artifact @document=N'{"artifactKind":"flight-promise:nerdery-dnr-sign-up-and-sign-in","text":"{\"contractId\":\"flight-promise.v1\",\"promiseId\":\"nerdery-dnr-sign-up-and-sign-in\",\"workClass\":\"owner-objective\",\"statement\":\"OV3 declares sign-up and sign-in for the Nerdery wildlife application through the DNR identity service, feature first: each declaration binds the retained bytes of its canonical feature and commits only when the check finds the binding CONFORMANT, and each stored document is exactly the reviewed one.\",\"obligations\":[{\"obligationId\":\"O1\",\"statement\":\"nerdery-sign-in-wildlife-user is declared from nerdery/dsl/nerdery-sign-in-wildlife-user.dsl, pinned to its canonical feature sha256:bf9ff42f4a1c96eec6cb938f3bf40e57b8c13aed9b94e4a64dc73f90b6250cd6, and its stored document is sha256:8d80e177396ad14f72b937aab911022b68f12b34b25fcd03628a9b8c21f389d9.\",\"evidence\":\"apply-declared-change COMMITTED; read-declared-capability-document $.documentDigest sha256:8d80e177396ad14f72b937aab911022b68f12b34b25fcd03628a9b8c21f389d9\"},{\"obligationId\":\"O2\",\"statement\":\"nerdery-register-wildlife-user is declared from nerdery/dsl/nerdery-register-wildlife-user.dsl, pinned to its canonical feature sha256:24ce719da85308c66551cae6d5f38a8477765ebff52dd7308e68db2dd7e0c666, and its stored document is sha256:a015138ada6c7327a6c802401f08a1e213d537d7c3b3dac8cee6be7ee555bb01.\",\"evidence\":\"apply-declared-change COMMITTED; read-declared-capability-document $.documentDigest sha256:a015138ada6c7327a6c802401f08a1e213d537d7c3b3dac8cee6be7ee555bb01\"}]}"}';
SELECT N'minted' AS result_set,ordinal,JSON_VALUE(value,'$.artifact_kind') AS artifact_kind,JSON_VALUE(value,'$.action') AS action,JSON_VALUE(value,'$.content_digest') AS content_digest FROM @minted ORDER BY ordinal;
DECLARE @want TABLE(ordinal int PRIMARY KEY,artifact_kind nvarchar(80),digest varchar(80));
INSERT @want VALUES(1,N'capability-feature:nerdery-sign-in-wildlife-user','sha256:bf9ff42f4a1c96eec6cb938f3bf40e57b8c13aed9b94e4a64dc73f90b6250cd6'),(2,N'capability-feature:nerdery-register-wildlife-user','sha256:24ce719da85308c66551cae6d5f38a8477765ebff52dd7308e68db2dd7e0c666'),(3,N'flight-promise:nerdery-dnr-sign-up-and-sign-in','sha256:afeedfa290e5ea7d6fe72f11a28427dad0190b6cb9506260c72cc8541f49a817');
SELECT N'readback' AS result_set,w.ordinal,w.artifact_kind,w.digest,CASE WHEN EXISTS(SELECT 1 FROM model.content_artifact a WHERE a.artifact_kind=w.artifact_kind COLLATE Latin1_General_100_BIN2 AND a.content_digest=CONVERT(binary(32),SUBSTRING(w.digest,8,64),2)) THEN 1 ELSE 0 END AS retained FROM @want w ORDER BY w.ordinal;
IF EXISTS(SELECT 1 FROM @want w WHERE NOT EXISTS(SELECT 1 FROM model.content_artifact a WHERE a.artifact_kind=w.artifact_kind COLLATE Latin1_General_100_BIN2 AND a.content_digest=CONVERT(binary(32),SUBSTRING(w.digest,8,64),2)))
